import type { MealType } from '@motivation/shared';
import { appNow } from '@motivation/shared';
import { getAppTimeZone } from '../../services/app-timezone.service.js';

export function activityIcon(type: string): string {
    switch (type) {
        // Snake-cased Strava sport_types (story 142).
        case 'running': return '🏃';
        case 'cycling': return '🚴';
        case 'swimming': return '🏊';
        case 'walking': return '🚶';
        case 'hiking': return '🥾';
        case 'tennis': return '🎾';
        case 'ice_skate': return '⛸️';
        case 'alpine_ski': return '⛷️';
        case 'hiit': return '🔥';
        case 'weight_training': return '🏋️';
        // Legacy values still present in historical rows pre-story-142.
        case 'gym': return '🏋️';
        case 'ice-skating': return '⛸️';
        default: return '💪';
    }
}

/** Compact duration for chips/summaries: 45 → '45m', 90 → '1h30m', 120 → '2h'. Empty for 0/undefined. */
export function formatDurationMinutes(minutes?: number): string {
    if (!minutes) return '';
    if (minutes >= 60) {
        const h = Math.floor(minutes / 60);
        const m = minutes % 60;
        return m > 0 ? `${h}h${m}m` : `${h}h`;
    }
    return `${minutes}m`;
}

/** Compact step counts for pills/labels: 8450 → '8.5k', 10000 → '10k', 900 → '900'. */
export function formatSteps(steps: number): string {
    if (steps < 1000) return String(Math.round(steps));
    return `${(steps / 1000).toFixed(1).replace(/\.0$/, '')}k`;
}

export function getDefaultMealType(hour: number = appNow(getAppTimeZone()).hour): MealType {
    if (hour < 11) return 'Breakfast';
    if (hour < 15) return 'Lunch';
    if (hour < 21) return 'Dinner';
    return 'Snacks';
}

// --- Activity start time (story 299) ---
//
// An activity has a `date` and a `duration_minutes` but had no time of day, which is fine for a
// day-shaped timeline and not enough for Health Connect: a record there is an *interval*. The
// start is kept in `metadata.start` as an ISO instant — the same key and the same format Health
// Connect rows have carried since story 250, so one convention covers both origins and the sync's
// existing reader works unchanged. It is optional: an activity without one is still a valid
// activity, just one the write-back has to place by convention.

/** `HH:MM` in the app timezone for an activity's stored start; empty string when it has none. */
export function activityStartLocalTime(metadata: string | null | undefined, timeZone: string = getAppTimeZone()): string {
    if (!metadata) return '';
    let start: unknown;
    try {
        start = (JSON.parse(metadata) as { start?: unknown }).start;
    } catch {
        return '';
    }
    if (typeof start !== 'string') return '';
    try {
        const local = Temporal.Instant.from(start).toZonedDateTimeISO(timeZone);
        return `${String(local.hour).padStart(2, '0')}:${String(local.minute).padStart(2, '0')}`;
    } catch {
        return '';
    }
}

/**
 * Folds a `HH:MM` local start into an activity's metadata, returning the JSON to store.
 *
 * An empty [localTime] removes the start rather than leaving the old one behind — clearing the
 * field has to be expressible, or the only way back from a mistyped time is a delete. That is why
 * this returns `'{}'` and never `undefined` for a cleared value: `undefined` is dropped by the
 * update path, which is the bug backlog item "clearing a set field is not expressible".
 */
export function withActivityStart(
    metadata: string | null | undefined,
    date: string,
    localTime: string,
    timeZone: string = getAppTimeZone(),
): string {
    let base: Record<string, unknown> = {};
    if (metadata) {
        try {
            const parsed = JSON.parse(metadata) as unknown;
            if (parsed && typeof parsed === 'object') base = { ...(parsed as Record<string, unknown>) };
        } catch {
            // A metadata blob we cannot read is replaced rather than merged into — it was not
            // ours to preserve.
        }
    }
    const time = localTime.trim();
    if (!time) {
        delete base.start;
    } else {
        base.start = Temporal.PlainDateTime.from(`${date}T${time.length === 5 ? `${time}:00` : time}`)
            .toZonedDateTime(timeZone)
            .toInstant()
            .toString();
    }
    return JSON.stringify(base);
}

/**
 * Keeps a log-activity dialog's start-time default at "now minus the duration typed so far", until
 * the user edits it themselves.
 *
 * Without a default this field would sit empty on every entry and the write-back would fall back to
 * a convention forever — the story's own lesson is that a flow only used deliberately does not get
 * used. "Now" is the moment of logging, which is the end of a session far more often than the
 * start, so the duration is subtracted; typing 50 minutes right after a class puts the start where
 * the class began. Touching the field stops the recomputation for good, because after that the
 * value is the user's answer and not a guess.
 */
export function wireStartTimeDefault(form: HTMLFormElement, now: () => Temporal.ZonedDateTime = () => Temporal.Now.zonedDateTimeISO(getAppTimeZone())): void {
    const start = form.querySelector<HTMLInputElement>('[name="start"]');
    const duration = form.querySelector<HTMLInputElement>('[name="duration"]');
    if (!start || !duration) return;

    const refresh = (): void => {
        if (start.dataset.touched) return;
        const minutes = parseInt(duration.value, 10);
        const at = now().subtract({ minutes: Number.isFinite(minutes) && minutes > 0 ? minutes : 0 });
        start.value = `${String(at.hour).padStart(2, '0')}:${String(at.minute).padStart(2, '0')}`;
    };

    start.addEventListener('input', () => { start.dataset.touched = '1'; });
    duration.addEventListener('input', refresh);
    // `reset` fires before the form is actually reset, so the recompute is deferred past it —
    // otherwise it would write a default the reset then wipes.
    form.addEventListener('reset', () => {
        delete start.dataset.touched;
        queueMicrotask(refresh);
    });
    refresh();
}
